  o+=R(600,238,70,20,"#263238",4)+'<circle cx="615" cy="248" r="4" fill="#e53935"/><circle cx="630" cy="248" r="4" fill="#fdd835"/><circle cx="645" cy="248" r="4" fill="#43a047"/>';
